// Imports
import SnackBar from "@/components/SnackBar.vue";
import LoadingNew from "@/components/LoadingNew.vue";
import { my_team_user_list } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  // Components
  components: {
    SnackBar,
    LoadingNew
  },
  //Props
  props: {
    searchValue: String
  },
  // Data
  data() {
    return {
      // Array properties
      headers: [{
        title: "User",
        key: "user_profile_pic_url",
        sortable: false
      }, {
        title: "Member ID",
        key: "member_id",
        sortable: false
      }, {
        title: "Phone",
        key: "user_contact_number",
        sortable: false
      }, {
        title: "Location",
        key: "location",
        sortable: false
      }, {
        title: "Group",
        key: "department",
        sortable: false
      }, {
        title: "Reporting Manager",
        key: "reporting_manager",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      tableData: [],
      originalTableData: [],
      roles: [],
      statuses: [],
      // Object properties
      SnackBarComponent: {},
      // String properties
      search: "",
      // Boolean properties
      tableLoading: false,
      fixed: true,
      isReporteesFilterActive: false,
      adminAppExists: false,
      // Number properties

      componentCheck: 0,
      currentPage: 1,
      height: 0,
      itemsPerPage: 20,
      totalItems: 0,
      windowHeight: 0,
      // Null properties
      selectedRole: null,
      selectedStatus: null,
      next_token: null
    };
  },
  // Lifecycle hooks
  async created() {
    this.isVisible = true;
    this.windowHeight = window.innerHeight - 240;
  },
  mounted() {
    this.fetch_admin_apps();
    this.get_my_team();
  },
  // Watchers
  watch: {
    currentPage(newVal) {
      const table = document.querySelector(".modern-data-table");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    },
    tableData: {
      handler(newVal) {
        const maxPage = Math.ceil(this.totalItems / this.itemsPerPage);
        if (this.currentPage > maxPage && maxPage > 0) {
          this.currentPage = 1;
        }
      },
      deep: true
    }
  },
  // Computed properties
  computed: {
    searchReadyItems() {
      const text = this.searchValue.toLowerCase();
      return this.sortedAndPaginatedItems?.filter(item => item.full_user_name.toLowerCase().includes(text) || item.user_email_id.toLowerCase().includes(text) || item.member_id.toLowerCase().includes(text) || item.location.toLowerCase().includes(text) || item.department.toLowerCase().includes(text) || item.reporting_manager.toLowerCase().includes(text));
    },
    sortedAndPaginatedItems() {
      const sortedItems = this.tableData.slice().sort((a, b) => {
        const aValue = a.full_user_name ? a.full_user_name : "";
        const bValue = b.full_user_name ? b.full_user_name : "";
        return aValue.localeCompare(bValue, undefined, {
          sensitivity: "base"
        });
      });

      // Then paginate
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  // Methods
  methods: {
    // Admin methods
    fetch_admin_apps() {
      const userObj = this.$store.getters.GetUserObj;
      if (userObj.user.user_type == "ADMIN" || userObj.user.user_type == "OWNER") {
        this.adminAppExists = true;
      }
    },
    open_settings() {
      this.$router.push("/home/AdminTeam");
    },
    // Data fetching methods
    async get_my_team() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(my_team_user_list, {
          input: {
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            limit: 1000,
            name_search: "",
            nextToken: null
          }
        }));
        var dataArray = [];
        var response = JSON.parse(result.data.my_team_user_list);
        if (response.Status == "SUCCESS") {
          dataArray = await this.fetch_S3_file(response.s3_team_url);
          if (dataArray && Array.isArray(dataArray)) {
            await this.filter_based_on_visibility(dataArray);
            const validItems = this.tableData.filter(item => item && item.full_user_name && item.full_user_name.trim() !== "");
            if (validItems.length !== this.tableData.length) {
              console.warn("Some items have missing or empty names!");
              this.tableData.forEach((item, index) => {
                if (!item.full_user_name || item.full_user_name.trim() === "") {
                  console.warn(`Item at index ${index} has missing name:`, item);
                }
              });
            }
            this.originalTableData = [...this.tableData];
          } else {
            console.warn("No valid data received from S3 file");
            this.tableData = [];
            this.totalItems = 0;
            this.originalTableData = [];
          }
          this.tableLoading = false;
        } else {
          this.tableLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
        console.error("Error in get_my_team:", error);
        let errorMessage = "An error occurred while fetching team data";
        if (error && error.errors && error.errors.length > 0) {
          errorMessage = error.errors[0].message;
        } else if (error && error.message) {
          errorMessage = error.message;
        }
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: errorMessage,
          timeout: 5000,
          Top: true
        };
      }
    },
    async fetch_S3_file(value) {
      var responseData = null;
      let data = null;
      try {
        const response = await fetch(value);
        if (!response.ok) {
          throw new Error("Failed to fetch the file");
        }
        responseData = await response.text();
        data = JSON.parse(responseData);
        if (data && data.message && data.message.data && Array.isArray(data.message.data)) {
          return data.message.data;
        } else {
          console.warn("Invalid data structure received from S3 file");
          return [];
        }
      } catch (error) {
        console.error("Error fetching S3 file:", error);
        this.errorMessage = "Error fetching file: " + error.message;
        return [];
      }
    },
    // Filtering methods
    filter_based_on_visibility(response) {
      var resposnearray = [];
      var teamVisbility = this.$store.getters.GetOrgDetails;
      let currentUser = this.$store.getters.GetUserObj.user;
      if (!response || !Array.isArray(response)) {
        console.warn("Invalid response data received");
        this.tableData = [];
        this.totalItems = 0;
        return;
      }
      if (!teamVisbility || !teamVisbility.organization) {
        console.warn("Organization details not available, showing all users");
        resposnearray = response;
        const sorted = resposnearray.sort((a, b) => a.full_user_name.localeCompare(b.full_user_name, undefined, {
          sensitivity: "base"
        }));
        this.totalItems = resposnearray.length;
        return this.tableData = sorted;
      }
      let currentEmail = this.$store.getters.GetUserObj.user.user_email_id;
      let currentLocation = this.$store.getters.GetUserObj.user.location;
      let currentDepartment = this.$store.getters.GetUserObj.user.department;
      if (teamVisbility.organization.team_visibilty == "ALL_USERS") {
        resposnearray = response;
      } else if (teamVisbility.organization.team_visibilty == "USER_REPORTES_ONLY") {
        resposnearray = response.filter(user => user.reporting_manager !== "N/A" && user.reporting_manager.includes(currentEmail));
      } else if (teamVisbility.organization.team_visibilty == "USER_REPORTIES_AND_REPORTING_MANAGER") {
        resposnearray = response.filter(user => {
          let isReportee = user.reporting_manager && user.reporting_manager !== "N/A" && user.reporting_manager.includes(currentEmail);
          let isManager = user.user_email_id === this.$store.getters.GetUserObj.user.reporting_manager && this.$store.getters.GetUserObj.user.reporting_manager !== "N/A";
          return isReportee || isManager;
        });
      } else if (teamVisbility.organization.team_visibilty == "USER_COMMON_LOCATION") {
        resposnearray = response.filter(user => user.location !== "N/A" && user.location.includes(currentLocation));
      } else if (teamVisbility.organization.team_visibilty == "USER_COMMON_DEPARTMENT") {
        resposnearray = response.filter(user => user.department !== "N/A" && user.department.includes(currentDepartment));
      } else if (teamVisbility.organization.team_visibilty == "USER_REPORTEES_AND_REPORTING_HIERARCHY") {
        // alert(4);
        let emailSet = new Set();
        emailSet.add(currentEmail);
        response.forEach(user => {
          if (user.reporting_manager && user.reporting_manager !== "N/A" && user.reporting_manager.includes(currentEmail)) {
            emailSet.add(user.user_email_id);
          }
        });
        let currentRM = currentUser.reporting_manager_email;
        while (currentRM && currentRM !== "N/A") {
          emailSet.add(currentRM);
          let rmUser = response.find(user => user.user_email_id === currentRM);
          if (!rmUser || !rmUser.reporting_manager || rmUser.reporting_manager === "N/A") {
            break;
          }
          currentRM = rmUser.reporting_manager;
        }
        resposnearray = response.filter(user => emailSet.has(user.user_email_id));
      } else if (teamVisbility.organization.team_visibilty == "USER_REPORTEES_AND_PEERS") {
        let peerManager = currentUser.reporting_manager_email;
        let emailSet = new Set();
        emailSet.add(currentEmail);
        response.forEach(user => {
          if (user.reporting_manager && user.reporting_manager !== "N/A" && user.reporting_manager.includes(currentEmail)) {
            emailSet.add(user.user_email_id);
          }
        });
        response.forEach(user => {
          if (peerManager && peerManager !== "N/A" && user.reporting_manager && user.reporting_manager.includes(peerManager)) {
            emailSet.add(user.user_email_id);
          }
        });
        resposnearray = response.filter(user => emailSet.has(user.user_email_id));
      }
      const sorted = resposnearray.sort((a, b) => a.full_user_name.localeCompare(b.full_user_name, undefined, {
        sensitivity: "base"
      }));
      this.tableData = sorted;
      this.totalItems = this.tableData.length;
      return this.tableData;
    },
    filterByReportees() {
      this.isReporteesFilterActive = !this.isReporteesFilterActive;
      if (this.isReporteesFilterActive) {
        if (this.originalTableData.length === 0) {
          this.originalTableData = [...this.tableData];
        }
        const currentEmail = this.$store.getters.GetUserObj.user.user_email_id;
        this.tableData = this.originalTableData.filter(user => user.reporting_manager !== "N/A" && user.reporting_manager.includes(currentEmail));
      } else {
        this.tableData = [...this.originalTableData];
      }
      this.totalItems = this.tableData.length;
      // Reset to first page when filtering
      this.currentPage = 1;
    },
    // Utility methods
    copyToClipboard_x_api_key(value) {
      const text = value;
      const el = document.createElement("textarea");
      el.value = text;
      el.setAttribute("readonly", "");
      el.style.position = "absolute";
      el.style.left = "-9999px";
      document.body.appendChild(el);
      el.select();
      document.execCommand("copy");
      document.body.removeChild(el);
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: "Copied Successfully",
        timeout: 5000,
        Top: true
      };
      window.open(value, "_blank");
    },
    fetch_value(val) {
      const d = new Date(parseInt(val));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      var dateValue = (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
      return dateValue;
    },
    // Navigation methods
    back_call() {
      this.$router.push("/UserlevelApp");
    },
    // UI interaction methods
    handle_row_click(value) {
      this.formInfo = value;
      this.componentCheck = 1;
      this.formDialog = true;
    },
    screen_refresh() {
      this.tableData = [];
      this.get_my_team();
    },
    get_myteam_Pagination() {
      if (this.next_token) {
        this.get_my_team();
      }
    },
    // Notification methods
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.formDialog = false;
    },
    // Reset and utility methods
    resetAll() {
      this.search = "";
      this.selectedRole = null;
      this.selectedStatus = null;
      this.isReporteesFilterActive = false;
      if (this.originalTableData.length > 0) {
        this.tableData = [...this.originalTableData];
        this.totalItems = this.tableData.length;
      } else {
        this.get_my_team();
      }
    }
  }
};
